      pt: ["O Wadi Kufranja alimenta a barragem local.", "A agricultura de irrigação tem aqui uma longa tradição.", "Numerosos trilhos de caminhada cruzam as florestas circundantes.", "Os verões aqui são agradavelmente suaves."],
      fr: ["Le Wadi Kufranja alimente le barrage local.", "L'agriculture irriguée possède ici une longue tradition.", "De nombreux sentiers de randonnée traversent les forêts environnantes.", "Les étés y sont agréablement doux."],
