    descriptionAdvanced: {
      de: "Kufranja liegt im Gouvernement Ajloun im Nordwesten Jordaniens, eingebettet in eine bergige Landschaft mit mediterranem Klima. Der Name der Stadt leitet sich vermutlich von dem arabischen Wort für 'Dorf' und einem Bezug zu den Franken (Kreuzfahrern) ab, was auf eine historische Präsenz während der Kreuzzüge hindeutet. Die Region ist bekannt für ihre dichten Wälder und die terrassierten Hänge, auf denen seit Jahrhunderten Olivenbäume kultiviert werden. Kufranja dient als wichtiges landwirtschaftliches Zentrum für die umliegenden Dörfer und profitiert von den reichlichen Niederschlägen der Ajloun-Berge. In der Nähe der Stadt befinden sich bedeutende historische Stätten wie die Burg Ajloun, die den strategischen Wert der Gegend unterstreicht. Heute ist die Stadt ein Symbol für ländliche Traditionen und die Bewahrung des ökologischen Erbes Jordaniens, wobei der Tourismus durch die natürliche Schönheit der Täler zunehmend an Bedeutung gewinnt.",
      hu: "Kufranja Jordánia északnyugati részén, Ajloun kormányzóságban található, egy hegyvidéki területen, amelyre a mediterrán éghajlat jellemző. A város neve valószínűleg a 'falu' és a 'frankok' (keresztes lovagok) szavak kombinációjából ered, utalva a keresztes hadjáratok idején fennálló jelenlétükre. A régió híres sűrű erdőiről és a teraszos hegyoldalakról, ahol évszázadok óta foglalkoznak olajbogyó-termesztéssel. Kufranja fontos mezőgazdasági központként szolgál a környező kistelepülések számára, kihasználva az Ajloun-hegység bőséges csapadékát. A város közelében található Ajloun vára, amely jól mutatja a terület történelmi stratégiai fontosságát a középkorban. Napjainkban a település a vidéki hagyományok és a jordániai ökológiai örökség megőrzésének egyik központja, ahol a természeti szépségek mentén a turizmus is fejlődésnek indult.",
      ro: "Kufranja este situat în guvernoratul Ajloun din nord-vestul Iordaniei, fiind așezat într-o zonă montană spectaculoasă cu o climă de tip mediteranean. Se crede că numele orașului derivă din limba arabă, însemnând 'satul francilor', ceea ce sugerează o legătură istorică cu perioada cruciadelor. Regiunea este celebră pentru pădurile sale dese și versanții terasați, unde cultivarea măslinilor este o tradiție milenară. Kufranja funcționează ca un centru agricol vital pentru satele din jur, beneficiind de precipitațiile bogate specifice munților Ajloun. În proximitatea orașului se află cetatea Ajloun, care atestă importanța strategică a zonei în timpul luptelor dintre cruciați și forțele ayyubide. În prezent, orașul reprezintă un punct de referință pentru tradițiile rurale și conservarea mediului înconjurător, atrăgând vizitatori datorită frumuseții naturale a văilor adiacente.",
      en: "Kufranja is situated in the Ajloun Governorate of northwestern Jordan, nestled within a mountainous landscape characterized by a Mediterranean climate. The town's name is believed to derive from the Arabic words for 'village' and 'Franks' (Crusaders), hinting at a historical presence during the Crusader period. This region is renowned for its dense forests and terraced hillsides, where olive cultivation has been practiced for centuries. Kufranja serves as a key agricultural hub for the surrounding rural communities, taking advantage of the relatively high rainfall in the Ajloun mountains. The town is located near the historic Ajloun Castle, which emphasizes the area's strategic significance during the Middle Ages. Today, it stands as a symbol of rural tradition and ecological preservation, with local tourism growing due to the natural scenic beauty of the nearby valleys.",
      es: "Kufranja se encuentra a unos 70 kilómetros al noroeste de Amán, a 700 metros de altitud en las montañas de Ajloun, y cuenta con unos 25.000 habitantes incluyendo las aldeas cercanas. El nombre procede posiblemente de la palabra aramea para pueblo de los francos, haciendo referencia a la presencia cruzada en la región. El Wadi Kufranja, un valle perenne con manantiales que fluyen todo el año, es uno de los valles más verdes de Jordania y atraviesa la ciudad. La presa de Kufranja, terminada en 2014 con una capacidad de 7,8 millones de metros cúbicos, sirve para el riego de la zona del valle del norte de Jordania. La región es famosa por sus olivares, plantados sistemáticamente en el siglo XIX por colonos circasianos y árabes; el aceite de oliva de Ajloun se considera uno de los de mayor calidad de Jordania. Durante el mandato británico (1921-1946), la región recibió apoyo económico.",
      pt: "Kufranja situa-se a cerca de 70 quilómetros a noroeste de Amã, a 700 metros de altitude nas montanhas de Ajloun, e conta com cerca de 25.000 habitantes incluindo as aldeias vizinhas. O nome provém possivelmente da palavra aramaica para aldeia dos francos, referindo-se a uma presença cruzada na região. O Wadi Kufranja, um vale perene com nascentes que correm todo o ano, é um dos vales mais verdes da Jordânia e atravessa a cidade. A barragem de Kufranja, concluída em 2014 com uma capacidade de 7,8 milhões de metros cúbicos, serve para a irrigação da zona do vale do norte da Jordânia. A região é famosa pelos seus olivais, plantados sistematicamente no século XIX por colonos circassianos e árabes; o azeite de Ajloun é considerado um dos de maior qualidade da Jordânia. Durante o mandato britânico (1921-1946), a região recebeu apoio económico.",
      fr: "Kufranja est située à environ 70 kilomètres au nord-ouest d'Amman, à 700 mètres d'altitude dans les montagnes d'Ajloun, et compte environ 25 000 habitants avec les villages environnants. Son nom provient peut-être du mot araméen signifiant village des Francs, en référence à une présence croisée dans la région. Le Wadi Kufranja, une vallée pérenne dotée de sources coulant toute l'année, est l'une des vallées les plus vertes de Jordanie et traverse la ville. Le barrage de Kufranja, achevé en 2014 avec une capacité de 7,8 millions de mètres cubes, sert à l'irrigation de la vallée du nord de la Jordanie. La région est réputée pour ses oliveraies, plantées systématiquement au XIXe siècle par des colons circassiens et arabes ; l'huile d'olive d'Ajloun est considérée comme l'une des plus qualitatives de Jordanie. Sous le mandat britannique (1921-1946), la région a bénéficié d'un soutien économique.",
    },
