      de: ["Der Name Kufranja bedeutet übersetzt 'Dorf der Franken'.", "Die Stadt liegt auf einer durchschnittlichen Höhe von etwa 600 Metern.", "Einige Olivenbäume in der Umgebung sind über 2.000 Jahre alt.", "Das Wadi Kufranja ist eines der wasserreichsten Täler der Region.", "Kufranja gehört zum administrativen Bezirk des Gouvernements Ajloun.", "Die Region verzeichnet im Winter oft Schneefälle."],
      hu: ["A Kufranja név jelentése magyarul 'a frankok faluja'.", "A város átlagos tengerszint feletti magassága 600 méter.", "A környéken található néhány olajfa kora meghaladja a 2000 évet.", "A Vádi Kufranja a régió egyik legfontosabb vízfolyása.", "A település az Ajloun kormányzóság közigazgatási egységéhez tartozik.", "A hegyvidéki elhelyezkedés miatt télen gyakori a havazás."],
