      en: ["The name Kufranja literally translates to 'the village of the Franks'.", "The town sits at an average elevation of approximately 600 meters.", "Some olive trees in the surrounding groves are over 2,000 years old.", "Wadi Kufranja is one of the most significant watercourses in the region.", "Kufranja is an administrative center within the Ajloun Governorate.", "The area frequently experiences snowfall during the winter months."],
      es: ["Unos 25.000 habitantes a 700 metros de altitud", "70 kilómetros al noroeste de Amán", "Nombre posiblemente derivado de 'pueblo de los francos'", "Wadi Kufranja con manantiales permanentes", "Presa de Kufranja terminada en 2014", "Capacidad del embalse de 7,8 millones de metros cúbicos", "Olivares plantados en el siglo XIX", "Mandato británico de 1921 a 1946"],
      pt: ["Cerca de 25.000 habitantes a 700 metros de altitude", "70 quilómetros a noroeste de Amã", "Nome possivelmente derivado de 'aldeia dos francos'", "Wadi Kufranja com nascentes permanentes", "Barragem de Kufranja concluída em 2014", "Capacidade da albufeira de 7,8 milhões de metros cúbicos", "Olivais plantados no século XIX", "Mandato britânico de 1921 a 1946"],
