      hu: "Al-Hasimijja egy feltörekvő város a Zarka régióban. Fontos szerepet játszik az ország villamosenergia- és energiatermelésében.",
      ro: "Al-Hashimiyah este un oraș în plină dezvoltare în regiunea Zarqa. Joacă un rol important în producția de energie electrică a țării.",
