      en: ["The Jordan Petroleum Refinery began its operations here in 1961.", "The Hashemite University was established in Al-Hashimiyah in 1995.", "The city is located approximately 10 kilometers north of Zarqa city.", "The Al-Hussein Thermal Power Station, Jordan's largest, is situated here.", "The region serves as a critical junction for the national pipeline network.", "Al-Hashimiyah has experienced some of the fastest urban growth in Jordan."],
      es: ["Unos 90.000 habitantes con los alrededores", "30 kilómetros al noreste de Amán", "Ciudad planificada de los años 70", "Nombrada en honor a la dinastía hachemita", "Universidad Hachemita fundada en 1991, abierta en 1995", "Cerca de 26.000 estudiantes en la universidad", "Central térmica King Hussein desde 1973, unos 600 megavatios", "Mandato Británico de 1921 a 1946"],
      pt: ["Cerca de 90.000 habitantes com arredores", "30 quilómetros a nordeste de Amã", "Cidade planeada dos anos 70", "Nomeada em honra da dinastia hachemita", "Universidade Hachemita fundada em 1991, aberta em 1995", "Cerca de 26.000 estudantes na universidade", "Central térmica King Hussein desde 1973, cerca de 600 megawatts", "Mandato Britânico de 1921 a 1946"],
      fr: ["Environ 90 000 habitants avec la périphérie", "30 kilomètres au nord-est d'Amman", "Ville planifiée des années 1970", "Nommée d'après la dynastie hachémite", "Université hachémite fondée en 1991, ouverte en 1995", "Environ 26 000 étudiants à l'université", "Centrale thermique King Hussein depuis 1973, environ 600 MW", "Mandat britannique de 1921 à 1946"],
