      es: ["El humedal de Azraq es una importante reserva natural.", "T. E. Lawrence utilizó el castillo local como base.", "El oasis perdió mucha agua debido al bombeo excesivo.", "Aquí se encuentran restos de fuertes romanos."],
      pt: ["O pântano de Azraq é uma reserva natural importante.", "T. E. Lawrence utilizou o castelo local como base.", "O oásis perdeu muita água devido à bombagem excessiva.", "Existem aqui vestígios de fortes romanos."],
      fr: ["La zone humide d'Azraq est une importante réserve naturelle.", "T. E. Lawrence a utilisé le château local comme base.", "L'oasis a perdu beaucoup d'eau à cause d'un pompage excessif.", "On y trouve des vestiges de castrums romains."],
