    descriptionAdvanced: {
      de: "Azraq ist eine einzigartige Oasenstadt in der östlichen Wüste Jordaniens, etwa 100 Kilometer östlich von Amman. Die Stadt war historisch gesehen ein lebenswichtiger Zwischenstopp für Karawanen und Pilger, da sie die einzige permanente Wasserquelle in einem weiten Umkreis bot. Das Herzstück der Stadt ist das Qasr Azraq, eine massive Festung aus schwarzem Basalt, die von den Römern errichtet und später von den Umayyaden und Osmanen genutzt wurde. Während der Arabischen Revolte diente die Festung T.E. Lawrence als Hauptquartier. Neben der historischen Bedeutung ist Azraq für sein Feuchtgebiet-Reservat bekannt, ein RAMSAR-Schutzgebiet, das als kritischer Rastplatz für Zugvögel zwischen Afrika und Eurasien dient. Trotz der ökologischen Herausforderungen durch Wasserentnahme bleibt Azraq ein strategischer Verkehrsknotenpunkt an der Kreuzung der Straßen nach Saudi-Arabien und in den Irak.",
      hu: "Azraq egy különleges oázisváros Jordánia keleti sivatagában, mintegy 100 kilométerre Ammántól. Történelmileg létfontosságú pihenőhely volt a karavánok és zarándokok számára, mivel hatalmas területen ez volt az egyetlen állandó édesvízforrás. A város jelképe a Qasr Azraq, egy fekete bazaltból épült erőd, amelyet a rómaiak alapítottak, majd az Omajjádok és az oszmánok is használtak. Az arab felkelés idején az erőd T.E. Lawrence (Arábiai Lawrence) főhadiszállásaként szolgált a sivatagi hadműveletek során. A történelmi örökség mellett Azraq a vizes élőhelyeiről (Azraq Wetland Reserve) nevezetes, amely a RAMSAR-egyezmény védelme alatt áll, és fontos pihenőhelye a vándorló madaraknak. Bár az intenzív vízszivattyúzás veszélyezteti az ökoszisztémát, a város továbbra is fontos stratégiai csomópont a Szaúd-Arábia és Irak felé vezető utak kereszteződésében.",
      ro: "Azraq este un oraș-oază distinctiv situat în deșertul estic al Iordaniei, la aproximativ 100 km de Amman. Din punct de vedere istoric, a fost un punct de oprire vital pentru caravane și pelerini, fiind singura sursă permanentă de apă dulce pe o rază de sute de kilometri. Punctul de reper principal este Qasr Azraq, o fortăreață masivă construită din bazalt negru, utilizată succesiv de romani, omeiazi și otomani. În timpul Revoltei Arabe din 1917, castelul a servit drept cartier general pentru T.E. Lawrence (Lawrence al Arabiei). Pe lângă importanța istorică, Azraq găzduiește Rezervația de Zone Umede, un sit protejat prin convenția RAMSAR, esențial pentru păsările migratoare între Africa și Eurasia. Deși extracția excesivă de apă a afectat ecosistemul, orașul rămâne un nod logistic strategic la intersecția rutelor comerciale către Arabia Saudită și Irak.",
      en: "Azraq is a unique oasis town in the eastern desert of Jordan, located approximately 100 kilometers east of Amman. Historically, it served as a vital watering hole and rest stop for caravans and pilgrims, being the only permanent source of fresh water in a vast arid region. The town is home to Qasr Azraq, a massive black basalt fortress originally built by the Romans and later expanded by the Umayyads and Ottomans. During the Arab Revolt of 1917, the castle famously served as the headquarters for T.E. Lawrence. Beyond its military history, Azraq is renowned for the Azraq Wetland Reserve, a RAMSAR-protected site that acts as a critical stopover for migratory birds traveling between Africa and Eurasia. Despite ecological pressures from groundwater extraction, Azraq remains a strategic crossroads connecting Jordan with Saudi Arabia and Iraq.",
      es: "Azraq (el Azul) se encuentra a unos 100 kilómetros al este de Amán, a 510 metros de altitud, y cuenta con unos 12.000 habitantes, entre ellos muchos chechenos y drusos. La ciudad fue un oasis clave en el cruce de rutas comerciales entre Arabia, Siria e Irak. El castillo Qasr al-Azraq, construido originalmente por los romanos hacia el año 200 d.C. y ampliado por los ayubíes en el siglo XIII con basalto negro, sirvió de cuartel general a T. E. Lawrence (Lawrence de Arabia) en el invierno de 1917/18 durante la Rebelión Árabe. El humedal de Azraq, que llegó a ser un oasis de 12 kilómetros cuadrados con dos manantiales permanentes, era lugar de descanso para millones de aves migratorias; debido a la extracción excesiva de agua para Amán desde los años 60, se secó casi por completo en 1992. Desde 1994, la Royal Society for the Conservation of Nature intenta restaurar la reserva (fundada en 1977) mediante el aporte de agua. Durante el mandato británico (1921-1946), Azraq fue un puesto estratégico en el desierto.",
      pt: "Azraq (o Azul) situa-se a cerca de 100 quilómetros a leste de Amã, a 510 metros de altitude, e conta com cerca de 12.000 habitantes, incluindo muitos chechenos e drusos. A cidade foi um oásis fundamental no cruzamento de rotas comerciais entre a Arábia, a Síria e o Iraque. O castelo Qasr al-Azraq, originalmente construído pelos romanos por volta de 200 d.C. e ampliado pelos ayubidas no século XIII com basalto negro, serviu de quartel-general a T. E. Lawrence (Lawrence da Arábia) no inverno de 1917/18 durante a Revolta Árabe. O pântano de Azraq, que outrora foi um oásis de 12 quilómetros quadrados com duas nascentes permanentes, era um local de descanso para milhões de aves migratórias; devido à extração excessiva de água para Amã desde os anos 60, secou quase completamente em 1992. Desde 1994, a Royal Society for the Conservation of Nature tenta restaurar a reserva (fundada em 1977) através do fornecimento de água. Durante o mandato britânico (1921-1946), Azraq foi um posto estratégico no deserto.",
      fr: "Azraq (le Bleu) se situe à environ 100 kilomètres à l'est d'Amman, à 510 mètres d'altitude, et compte environ 12 000 habitants, dont de nombreux Tchétchènes et Druzes. La ville fut pendant des millénaires une oasis clé au croisement des routes caravanières entre l'Arabie, la Syrie et l'Irak. Le château Qasr al-Azraq, érigé à l'origine par les Romains vers 200 apr. J.-C. et agrandi par les Ayyoubides au XIIIe siècle avec du basalte noir, servit de quartier général à T. E. Lawrence (Lawrence d'Arabie) durant l'hiver 1917/18 lors de la Révolte arabe. La zone humide d'Azraq, autrefois une oasis de 12 kilomètres carrés avec deux sources permanentes, accueillait des millions d'oiseaux migrateurs ; l'extraction excessive d'eau pour Amman dès les années 1960 a conduit à son assèchement quasi total en 1992. Depuis 1994, la Royal Society for the Conservation of Nature s'efforce de restaurer la réserve (créée en 1977) par apport d'eau. Sous le mandat britannique (1921-1946), Azraq était un poste stratégique du désert.",
    },
